package com.sanai.cleaner;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.DocumentsContract;import java.io.*;import java.security.MessageDigest;import java.util.*;import org.json.*;

final class Quarantine {
 final Context c; final ContentResolver cr; final File root;
 Quarantine(Context c){this.c=c;cr=c.getContentResolver();root=new File(c.getFilesDir(),"quarantine");root.mkdirs();}
 static final class Entry {File dir,content;JSONObject meta;String name(){return meta.optString("name");}long size(){return content.length();}}
 List<Entry> entries(){ArrayList<Entry> out=new ArrayList<>();File[] ds=root.listFiles();if(ds!=null)for(File d:ds)try{Entry e=new Entry();e.dir=d;e.content=new File(d,"content");e.meta=new JSONObject(new String(java.nio.file.Files.readAllBytes(new File(d,"meta.json").toPath()),java.nio.charset.StandardCharsets.UTF_8));if(e.content.isFile())out.add(e);}catch(Exception ignored){}return out;}
 static String digest(InputStream in,OutputStream out,long limit)throws Exception{MessageDigest md=MessageDigest.getInstance("SHA-256");byte[] b=new byte[131072];long total=0;try(InputStream source=in){if(source==null)throw new IOException("no source");int n;while((n=source.read(b))!=-1){total+=n;if(total>limit)throw new IOException("size changed");md.update(b,0,n);if(out!=null)out.write(b,0,n);}}return java.util.Base64.getEncoder().encodeToString(md.digest());}
 Entry move(ScanEngine.Item i)throws Exception{if(i.media||i.protectedFile||i.parent.isEmpty()||i.size<=0||i.modified<=0)throw new IOException("not eligible");try(Cursor q=cr.query(i.uri,new String[]{"_size","last_modified","flags"},null,null,null)){if(q==null||!q.moveToFirst()||q.getLong(0)!=i.size||q.getLong(1)!=i.modified||(q.getInt(2)&DocumentsContract.Document.FLAG_SUPPORTS_DELETE)==0)throw new IOException("document changed or delete unsupported");}if(root.getUsableSpace()<i.size+10_000_000L)throw new IOException("not enough free space for backup");Entry e=new Entry();e.dir=new File(root,UUID.randomUUID().toString());if(!e.dir.mkdir())throw new IOException("mkdir");e.content=new File(e.dir,"content");boolean committed=false;try{String hash;try(FileOutputStream out=new FileOutputStream(e.content)){hash=digest(cr.openInputStream(i.uri),out,i.size);out.getFD().sync();}if(e.content.length()!=i.size||!hash.equals(digest(new FileInputStream(e.content),null,i.size))||!hash.equals(digest(cr.openInputStream(i.uri),null,i.size)))throw new IOException("backup verification");e.meta=new JSONObject();e.meta.put("name",i.name).put("mime",i.mime).put("parent",i.parent).put("original",i.key()).put("sha",hash).put("size",i.size);try(FileOutputStream out=new FileOutputStream(new File(e.dir,"meta.json"))){out.write(e.meta.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));out.getFD().sync();}committed=true;if(!DocumentsContract.deleteDocument(cr,i.uri))throw new IOException("provider rejected deletion; backup retained");return e;}finally{if(!committed){e.content.delete();new File(e.dir,"meta.json").delete();e.dir.delete();}}}
 void restore(Entry e)throws Exception{String expected=e.meta.getString("sha");long size=e.meta.getLong("size");if(e.content.length()!=size||!expected.equals(digest(new FileInputStream(e.content),null,size)))throw new IOException("backup integrity");Uri parent=Uri.parse(e.meta.getString("parent"));Uri dest=DocumentsContract.createDocument(cr,parent,e.meta.getString("mime"),e.name());if(dest==null)throw new IOException("create failed");try{try(OutputStream out=cr.openOutputStream(dest,"w")){if(out==null)throw new IOException("write failed");digest(new FileInputStream(e.content),out,size);}if(!expected.equals(digest(cr.openInputStream(dest),null,size)))throw new IOException("restore verification");}catch(Exception x){try{DocumentsContract.deleteDocument(cr,dest);}catch(Exception ignored){}throw x;}purge(e);}
 void purge(Entry e)throws IOException{if(!e.content.delete())throw new IOException("purge failed");new File(e.dir,"meta.json").delete();e.dir.delete();}
}